/// Returns an index of a minimal element in the subarray `a[lo..]`.
/// Preconditions (assumed by the problem statement):
/// - `a.len() > 0`
/// - `lo < a.len()`
pub fn find_min(a: &[i32], lo: usize) -> usize {
    debug_assert!(!a.is_empty(), "array must be non-empty");
    debug_assert!(lo < a.len(), "lo must be within array bounds");

    let mut min_idx = lo;
    for i in (lo + 1)..a.len() {
        if a[i] < a[min_idx] {
            min_idx = i;
        }
    }
    min_idx
}

